struct CAnimSetRetail { unsigned char EarlierState[0x2c]; float Speed; unsigned char MiddleState[0x08]; float LastAlpha; unsigned char LaterState[0x15]; unsigned char StateFlags; void SetAsFinished(long frames); }; void CAnimSetRetail::SetAsFinished(long frames) { const unsigned char Finished = 0x02; if ((StateFlags & Finished) != 0) return; StateFlags |= Finished; if (frames < 1) frames = 1; LastAlpha = Speed / (float)frames; }